describe('In-app Notifications Real-time Update', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display real-time notifications without page refresh', () => {
    // Intercept the API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');

    // Verify initial state: no notifications displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Trigger notification API call
    cy.get('[data-testid="notification-button"]').click();

    // Wait for API response
    cy.wait('@getNotifications');

    // Verify notification is displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'New message');

    // Verify notification appears without page refresh
    cy.get('[data-testid="notification-item"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="notification-item"]').should('not.have.class', 'is-loading');

    // Verify notification is real-time updated
    cy.intercept('GET', '/api/notifications').as('updateNotifications');
    cy.get('[data-testid="notification-button"]').click();
    cy.wait('@updateNotifications');

    // Verify updated notification is displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'Updated status');
  });

  it('should handle empty notification state gracefully', () => {
    // Intercept the API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');

    // Verify initial state: no notifications displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Trigger notification API call
    cy.get('[data-testid="notification-button"]').click();

    // Wait for API response
    cy.wait('@getNotifications');

    // Verify notification is displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'No new messages');

    // Verify empty state is handled gracefully
    cy.get('[data-testid="notification-item"]').should('have.class', 'empty');
    cy.get('[data-testid="notification-item"]').should('not.contain', 'Loading');

    // Verify user is notified of empty state
    cy.get('[data-testid="notification-item"]').should('contain', 'No new messages');
  });
});
